/**
 * Differential test: src/abi/v22-funding.ts vs the program's Rust funding fns.
 * Table generated by scripts/funding-rate-rust-diff/gen.rs (fns copied verbatim from
 * percolator-prog feat/v22-rc23-2026-10-22 d27f3d73, v16_program.rs:13129 and vault_lp_v18.rs:272/301).
 */
import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import {
  premiumFundingRateE9V22,
  skewFundingRateE9V22,
  combineFundingRateE9V22,
} from "../src/abi/v22-funding.js";

const here = dirname(fileURLToPath(import.meta.url));
const table = JSON.parse(readFileSync(join(here, "fixtures/funding-rate-rust-diff.json"), "utf8")) as {
  prog_commit: string;
  premium: [string, string, string, string | null][];
  skew: [string, string, string, string, string][];
  combine: [string, string, string, string][];
};

const U64 = (1n << 64n) - 1n;
const U64_MAX_PRODUCT_LIMIT = 1n << 128n;

describe("funding rate Rust differential", () => {
  it("table size >= 20k and pins the prog commit", () => {
    expect(table.prog_commit).toBe("d27f3d73b1a704bc398cdd27f400c12bd421e562");
    expect(table.premium.length + table.skew.length + table.combine.length).toBeGreaterThanOrEqual(20000);
  });

  it("premium matches Rust (None never occurs: u64*1e9 fits u128)", () => {
    const mism: string[] = [];
    for (const [m, x, c, exp] of table.premium) {
      if (exp === null) { mism.push(`${m},${x},${c}: rust=None`); continue; }
      const got = premiumFundingRateE9V22(BigInt(m), BigInt(x), BigInt(c));
      if (got !== BigInt(exp!)) mism.push(`${m},${x},${c}: ts=${got} rust=${exp}`);
    }
    expect(mism).toEqual([]);
  });

  it("skew matches Rust except the unreachable u128-overflow arm (> engine MAX_OI_SIDE_Q 1e14)", () => {
    const mism: string[] = [];
    let overflowArm = 0;
    for (const [lp, oi, s, m, exp] of table.skew) {
      const [lpB, oiB, sB, mB] = [BigInt(lp), BigInt(oi), BigInt(s), BigInt(m)];
      const got = skewFundingRateE9V22(lpB, oiB, sB, mB);
      if (got === BigInt(exp)) continue;
      const abs = lpB < 0n ? -lpB : lpB;
      const share = abs > oiB ? oiB : abs;
      // Documented divergence: Rust returns 0 on overflow of slope*share; the bigint port returns the cap.
      if (sB * share >= U64_MAX_PRODUCT_LIMIT && BigInt(exp) === 0n && oiB > 100_000_000_000_000n) {
        overflowArm++;
        continue;
      }
      mism.push(`${lp},${oi},${s},${m}: ts=${got} rust=${exp}`);
    }
    expect(mism).toEqual([]);
    // eslint-disable-next-line no-console
    console.log(`skew overflow-arm divergences (oi > 1e14, unreachable): ${overflowArm}`);
  });

  it("skew overflow arm: Rust 0 vs TS cap, only for oi_side beyond engine bound", () => {
    // slope u64::MAX * share 2^64 overflows u128; oi 2^64 > 1e14.
    const oi = 1n << 64n;
    expect(skewFundingRateE9V22(-oi, oi, U64, U64)).toBe(U64);
    // In the engine-valid range there is no divergence by construction (slope*1e14 < 2^128).
    expect(U64 * 100_000_000_000_000n < U64_MAX_PRODUCT_LIMIT).toBe(true);
  });

  it("combine matches Rust (saturating_add never changes the clamped result)", () => {
    const mism: string[] = [];
    for (const [p, s, m, exp] of table.combine) {
      const got = combineFundingRateE9V22(BigInt(p), BigInt(s), BigInt(m));
      if (got !== BigInt(exp)) mism.push(`${p},${s},${m}: ts=${got} rust=${exp}`);
    }
    expect(mism).toEqual([]);
  });
});
